<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Text Frequency Counter','description'=>'Count how often each word appears in a text.','url'=>'https://smarttoolz.in/tools/text-frequency-counter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Text Frequency Counter</h1><p>Count repeated words in your text.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="12" placeholder="Paste text..."></textarea><button id="go" class="tool-btn">Count Words</button><pre id="o"></pre></div></section></main><script>go.onclick=()=>{let m={};(i.value.toLowerCase().match(/[\p{L}\p{N}']+/gu)||[]).forEach(w=>m[w]=(m[w]||0)+1);o.textContent=Object.entries(m).sort((a,b)=>b[1]-a[1]).map(x=>`${x[0]}: ${x[1]}`).join('\n')||'No words.'}</script><?php smarttoolz_tool_page_end(); ?>